  for (int i=0; i<array.length-1; ++i) {
    Comparable c = array[i];
    int cIndex = i;
    for (int j=i+1; j<array.length; ++j)
      if (c.compareTo(array[j])>0) {
        c = array[j];
        cIndex = j;
      }
    array[cIndex] = array[i];
    array[i] = c;
  }
}

